"""Billing: charge an order."""
import os

from . import db
from .queue import BillingQueue


def bill(order, retries: int = 2):
    """Charge it."""
    queue = BillingQueue(os.environ.get("QUEUE_URL"))
    queue.post_event(order)
    return db.save(order)


def _private():
    return 1


if __name__ == "__main__":
    bill(None)

"""Storage."""


def save(order):
    """Write one order."""
    return order


class Ledger:
    """Every charge, once."""

    def post_entry(self, entry):
        return entry

    def _hidden(self):
        return 0

"""The queue of billing events."""


class BillingQueue:
    def __init__(self, url):
        self.url = url

    def post_event(self, event):
        return event

    def drain_events(self):
        return []

use std::fs;

